import{_ as t,c as o,o as d,a2 as c}from"./chunks/framework.lHtoIQ2D.js";const h=JSON.parse('{"title":"c++ 큐 구조","description":"","frontmatter":{},"headers":[],"relativePath":"Tech/~/ps/cpp-queue.md","filePath":"Tech/~/ps/cpp-queue.md","lastUpdated":1785799911000}'),a={name:"Tech/~/ps/cpp-queue.md"};function r(s,e,i,l,n,u){return d(),o("div",null,e[0]||(e[0]=[c(`<h1 id="c-큐-구조" tabindex="-1">c++ 큐 구조 <a class="header-anchor" href="#c-큐-구조" aria-label="Permalink to &quot;c++ 큐 구조&quot;">​</a></h1><h2 id="queue-vs-vector" tabindex="-1">queue vs vector <a class="header-anchor" href="#queue-vs-vector" aria-label="Permalink to &quot;queue vs vector&quot;">​</a></h2><ul><li><code>vector</code>: 연속된 메모리 블록. 인덱싱/순회 자유롭지만 맨 앞 삽입/삭제는 O(n) (기존 원소를 다 밀어야 함)</li><li><code>queue</code>: 컨테이너 어댑터. 내부적으로 기본값은 <code>deque</code>를 사용. <code>push()</code>(뒤에 추가), <code>pop()</code>(앞에서 제거), <code>front()</code>, <code>back()</code>, <code>size()</code>, <code>empty()</code>만 제공 — 인덱싱/순회 불가</li><li>&quot;이 자료구조는 FIFO로만 쓴다&quot;는 의도를 컴파일 타임에 강제하는 역할도 겸함</li></ul><h2 id="deque가-양-끝-o-1-인-이유" tabindex="-1">deque가 양 끝 O(1)인 이유 <a class="header-anchor" href="#deque가-양-끝-o-1-인-이유" aria-label="Permalink to &quot;deque가 양 끝 O(1)인 이유&quot;">​</a></h2><p><code>deque</code>는 하나의 연속 블록이 아니라, <strong>고정 크기 블록(chunk) 여러 개 + 그 블록들의 주소를 담은 지도(map)</strong> 구조.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[블록1: 원소들...] [블록2: 원소들...] [블록3: 원소들...]</span></span>
<span class="line"><span>     ↑ 블록 내부는 연속 배열(캐시 친화적), 블록끼리는 포인터로 연결</span></span></code></pre></div><ul><li>각 블록은 처음부터 여유 슬롯을 앞뒤로 남겨두고 할당됨</li><li>앞/뒤에 여유 슬롯이 있으면 -&gt; 그냥 그 자리에 쓰고 시작/끝 커서만 이동 (기존 원소 이동 없음)</li><li>여유 슬롯이 다 떨어지면 -&gt; 새 블록을 만들어 지도에 등록 (역시 기존 원소 이동 없음)</li></ul><p>→ <code>vector</code>의 <code>push_back</code> 상수배 재할당 전략을, <strong>블록 단위로 양쪽 끝에 동시에</strong> 적용한 것과 같음. 재할당 비용이 &quot;전체 복사&quot;가 아니라 &quot;블록 하나 추가&quot;라 훨씬 저렴함.</p><h2 id="왜-순수-링크드-리스트로-안-만들었나" tabindex="-1">왜 순수 링크드 리스트로 안 만들었나 <a class="header-anchor" href="#왜-순수-링크드-리스트로-안-만들었나" aria-label="Permalink to &quot;왜 순수 링크드 리스트로 안 만들었나&quot;">​</a></h2><p><code>deque</code>는 큐 전용이 아니라 <strong>O(1) 인덱싱(<code>d[i]</code>)까지 지원하는 범용 컨테이너</strong>로 설계됨.</p><table tabindex="0"><thead><tr><th></th><th>양 끝 O(1)</th><th>O(1) 인덱싱</th><th>캐시 효율</th></tr></thead><tbody><tr><td><code>vector</code></td><td>✗(앞쪽)</td><td>✓</td><td>✓</td></tr><tr><td>순수 링크드 리스트</td><td>✓</td><td>✗ (O(n))</td><td>✗</td></tr><tr><td><code>deque</code> (블록+지도)</td><td>✓</td><td>✓</td><td>△ (블록 내부만)</td></tr></tbody></table><ul><li>링크드 리스트는 원소 하나마다 개별 힙 할당 + 앞뒤 포인터 필요 → <code>int</code> 하나 저장하는 데 포인터 오버헤드가 더 큼</li><li><code>deque</code>는 블록 단위로 뭉쳐서 할당하므로 이 오버헤드가 훨씬 적고, 인덱싱도 O(1)로 가능</li></ul><p><code>std::queue</code>는 기본 내부 컨테이너로 <code>deque</code>를 재사용 — 큐 전용 자료구조를 새로 안 만들고 이미 다재다능하게 설계된 <code>deque</code>를 어댑터로 감싼 것.</p><h2 id="다른-언어의-데크-구현-비교" tabindex="-1">다른 언어의 데크 구현 비교 <a class="header-anchor" href="#다른-언어의-데크-구현-비교" aria-label="Permalink to &quot;다른 언어의 데크 구현 비교&quot;">​</a></h2><p>같은 &quot;양 끝 O(1)&quot;이라는 목표를, 언어마다 다른 방식으로 구현함.</p><ul><li><strong>C++ <code>std::deque</code></strong>: 블록 + 지도 (chunked)</li><li><strong>Java <code>ArrayDeque</code>, Rust <code>VecDeque</code></strong>: 원형 버퍼(circular buffer). 배열 하나에 시작/끝 인덱스를 순환시킴 (<code>% capacity</code>). 꽉 차면 <code>vector</code>처럼 통째로 재할당. 구조가 단순하고 캐시 효율 좋음</li><li><strong>Java <code>LinkedList</code>, Go <code>container/list</code></strong>: 순수 링크드 리스트. 양 끝 O(1)은 쉽지만 인덱싱 불가, 캐시 효율 최악</li><li><strong>Python <code>collections.deque</code></strong>: C++과 유사하게 고정 크기 블록의 이중연결리스트</li><li><strong>Go</strong>: 표준 라이브러리에 전용 데크 없음. 슬라이스 기반 원형 버퍼를 직접 구현하거나 <code>container/list</code> 사용</li></ul>`,16)]))}const q=t(a,[["render",r]]);export{h as __pageData,q as default};
